  Partition  1 : lag =      0
  Partition  2 : lag =      0
  Partition  3 : lag =      0
  Partition  4 : lag =      0
  Partition  5 : lag =      0
  Partition  6 : lag =      0
  Partition  7 : lag =      0
  Partition  8 : lag =      0
  Partition  9 : lag =      0
  Partition 10 : lag =      0
